"""解析规则文件中的路径表达式。支持：- `*` / `?` / `[...]` glob 通配- 结尾选择器 `(:last-modified)`：在匹配结果中取修改时间最新的一个- 路径组件 `:latest-modified`：在该层级取修改时间最新的子目录"""from itertools import productfrom pathlib import Path_LAST_MODIFIED_SUFFIX = '(:last-modified)'_LATEST_MODIFIED = ':latest-modified'def _has_magic(s: str) -> bool:    return any(c in s for c in '*?[{')def _expand_braces(part: str) -> list[str]:    """展开单层花括号选择：example.{rsa,crt} -> [example.rsa, example.crt]"""    if '{' not in part:        return [part]    results = ['']    for chunk in _split_brace_chunks(part):        if isinstance(chunk, list):            results = [p + alt for p in results for alt in chunk]        else:            results = [p + chunk for p in results]    return resultsdef _split_brace_chunks(part: str) -> list:    chunks: list = []    buf = ''    i = 0    while i < len(part):        c = part[i]        if c == '{':            end = part.find('}', i)            if end == -1:                raise ValueError(f'花括号未闭合: {part}')            if buf:                chunks.append(buf)                buf = ''            chunks.append(part[i + 1:end].split(','))            i = end + 1        else:            buf += c            i += 1    if buf:        chunks.append(buf)    return chunksdef resolve_pattern(pattern: str, root: Path) -> list[Path]:    """将规则中的路径表达式解析为具体的文件/目录列表（绝对路径）。"""    pattern = pattern.strip()    select_last = False    if pattern.endswith(_LAST_MODIFIED_SUFFIX):        select_last = True        pattern = pattern[: -len(_LAST_MODIFIED_SUFFIX)]    absolute = pattern.startswith('/')    parts = [p for p in pattern.split('/') if p not in ('', '.')]    current: list[Path] = [Path('/')] if absolute else [root]    for part in parts:        if part == _LATEST_MODIFIED:            candidates = [                d                for base in current                if base.is_dir()                for d in base.iterdir()                if d.is_dir()            ]            if not candidates:                raise FileNotFoundError(                    f'没有找到 :latest-modified 对应的子目录: {pattern}'                )            current = [max(candidates, key=lambda p: p.stat().st_mtime)]        elif _has_magic(part):            variants = _expand_braces(part)            nxt: list[Path] = []            for base in current:                if base.is_dir():                    for variant in variants:                        nxt.extend(base.glob(variant))            current = list(dict.fromkeys(nxt))        else:            current = [base / part for base in current]    if select_last:        if not current:            raise FileNotFoundError(f'路径没有匹配到任何文件: {pattern}')        current = [max(current, key=lambda p: p.stat().st_mtime)]    return current